import json
import logging
import os
import uuid
from datetime import datetime, timezone
from typing import Any, Dict, Iterable, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError

AWS_REGION = os.getenv("AWS_REGION", "us-east-1")
DEFAULT_LOG_GROUP = os.getenv("CLOUDWATCH_LOG_GROUP", "/application/logs")
DEFAULT_LOG_STREAM = os.getenv("CLOUDWATCH_LOG_STREAM", "application")
APP_NAME = os.getenv("APP_NAME", "managed-log-writer")


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _serialize_event(event: Dict[str, Any]) -> str:
    return json.dumps(event, ensure_ascii=False, separators=(",", ":"))


def _ensure_stream(client, log_group: str, log_stream: str) -> None:
    try:
        client.create_log_group(logGroupName=log_group)
    except ClientError as exc:
        if exc.response.get("Error", {}).get("Code") != "ResourceAlreadyExistsException":
            raise

    try:
        client.create_log_stream(logGroupName=log_group, logStreamName=log_stream)
    except ClientError as exc:
        if exc.response.get("Error", {}).get("Code") != "ResourceAlreadyExistsException":
            raise


def _get_sequence_token(client, log_group: str, log_stream: str) -> Optional[str]:
    try:
        response = client.describe_log_streams(
            logGroupName=log_group,
            logStreamNamePrefix=log_stream,
            limit=1,
        )
    except (BotoCoreError, ClientError):
        return None

    streams = response.get("logStreams", [])
    if not streams:
        return None
    return streams[0].get("uploadSequenceToken")


def write_log_events(
    events: Iterable[Dict[str, Any]],
    request_id: Optional[str] = None,
    log_group: Optional[str] = None,
    log_stream: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Write application log events to Amazon CloudWatch Logs with a shared correlation ID.

    Each event is enriched with:
      - request_id: shared correlation identifier
      - app_name: application identifier
      - timestamp: UTC ISO-8601 timestamp

    Returns a summary dict with the request_id, log_group, log_stream, and CloudWatch response.
    """
    correlation_id = request_id or str(uuid.uuid4())
    group_name = log_group or DEFAULT_LOG_GROUP
    stream_name = log_stream or DEFAULT_LOG_STREAM

    client = boto3.client("logs", region_name=AWS_REGION)
    _ensure_stream(client, group_name, stream_name)

    log_entries: List[Dict[str, Any]] = []
    for event in events:
        enriched = dict(event)
        enriched["request_id"] = correlation_id
        enriched["app_name"] = APP_NAME
        enriched.setdefault("timestamp", _utc_now_iso())
        log_entries.append(
            {
                "timestamp": int(datetime.now(timezone.utc).timestamp() * 1000),
                "message": _serialize_event(enriched),
            }
        )

    log_entries.sort(key=lambda item: item["timestamp"])

    put_kwargs = {
        "logGroupName": group_name,
        "logStreamName": stream_name,
        "logEvents": log_entries,
    }

    sequence_token = _get_sequence_token(client, group_name, stream_name)
    if sequence_token:
        put_kwargs["sequenceToken"] = sequence_token

    try:
        response = client.put_log_events(**put_kwargs)
    except ClientError as exc:
        error_code = exc.response.get("Error", {}).get("Code")
        if error_code == "InvalidSequenceTokenException":
            next_token = exc.response["Error"].get("Message", "").split()[-1]
            put_kwargs["sequenceToken"] = next_token
            response = client.put_log_events(**put_kwargs)
        elif error_code == "DataAlreadyAcceptedException":
            response = {"accepted": True, "request_id": correlation_id}
        else:
            raise

    return {
        "request_id": correlation_id,
        "log_group": group_name,
        "log_stream": stream_name,
        "cloudwatch_response": response,
    }


def write_single_log_event(
    message: str,
    level: str = "INFO",
    request_id: Optional[str] = None,
    extra: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    payload = {
        "message": message,
        "level": level,
        "extra": extra or {},
    }
    return write_log_events([payload], request_id=request_id)


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    result = write_log_events(
        [
            {"message": "request started", "level": "INFO"},
            {"message": "request completed", "level": "INFO", "duration_ms": 123},
        ]
    )
    print(json.dumps(result, default=str))
